records=F+T
ledger=[]
for item in records:
 p=subprocess.run(['rg','--json','-i',item['query'],str(CONTEXT)],capture_output=True,text=True)
 if p.returncode not in (0,1):raise RuntimeError(p.stderr)
 hits=[];counts={}
 for line in p.stdout.splitlines():
  r=json.loads(line)
  if r.get('type')!='match':continue
  d=r['data'];file=str(Path(d['path']['text']).relative_to(CONTEXT));counts[file]=counts.get(file,0)+1
  if counts[file]<=3:hits.append({'file':file,'line':d['line_number'],'text':d['lines']['text'].strip()[:350]})
 assert hits,item['id']
 ledger.append({'note':item['id'],'timestamp_utc':datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M:%S UTC'),'query':item['query'],'match_counts':counts,'sample_hits':hits,'selected_context':item['context'],'relation':item['status']})
(ROOT/'research/census_data.json').write_text(json.dumps(records,ensure_ascii=False,indent=2)+'\n')
(ROOT/'research/census_search_ledger.json').write_text(json.dumps(ledger,ensure_ascii=False,indent=2)+'\n')
def esc(x):return x.replace('|','\\|').replace('\n',' ')
text='# Standing question1: steps the manuscript itself marks as unverified\n\nThis census keeps explicit hedges, question marks, assumed steps, and same-text withdrawals distinct from claims merely lacking a proof. Each item was searched in the supplied context; detailed arguments and register connections are in the named notes. Context relations and follow-up status are part of each item, not declarations that a prior project has established it.\n\n| ID and kind | Cote/scan and place | Short manuscript words | Status and context relation | Context location; detailed notes |\n|---|---|---|---|---|\n'
for i in F:text+='| '+' | '.join(map(esc,[i['id']+' — '+i['kind'],i['location'],i['quote'],i['status'],i['context']+'; '+i['notes']]))+' |\n'
text+='\n# Standing question2: title sheets, headings, dates, and page counts\n\nThe census distinguishes actual written headings and numbers from modern editorial titles, archive foliation, printed job identifiers, and the number of scan images supplied. No cover sheet is present in this packet.\n\n| ID | Cote/scan and place | Written title or number | Census result and context relation | Context location |\n|---|---|---|---|---|\n'
for i in T:text+='| '+' | '.join(map(esc,[i['id'],i['location'],i['quote'],i['status'],i['context']]))+' |\n'
(ROOT/'research/censuses.md').write_text(text)
now=datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M:%S UTC')
with (ROOT/'research/census_checks.tsv').open('w',newline='') as f:
 w=csv.writer(f,delimiter='\t');w.writerow(['statement_id','date','who','type','outcome'])
 for i in records:w.writerow([i['id'],now,'GPT-6 Astra Pro; effort not exposed; run MPL_67_053-101/root research','carried as background without fault found','Textual census and context comparison; not a proof check. '+i['status']])
print(json.dumps({'self_flagged_items':len(F),'title_count_items':len(T),'context_searches':len(ledger),'all_searches_have_hits':True}))
